.navbars-style-11 { background: var(--primary-light); border-bottom: 1px solid #c5dfff; padding: 16px 0; }
.navbars-style-11 .navbar-brand { color: var(--black); font-size: 20px; }
.navbars-style-11 .brand-badge { width: 36px; height: 36px; border-radius: 8px; background: var(--primary); color: #fff; display: inline-flex; align-items: center; justify-content: center; }
.navbars-style-11 .nav-link { color: var(--dark-2); font-weight: 500; padding: 8px 12px; transition: color .2s; }
.navbars-style-11 .nav-link:hover, .navbars-style-11 .nav-link.active { color: var(--primary); }
.navbars-style-11 .navbar-toggler { color: var(--black); border: 1px solid #c5dfff; }
